module TopModule (
    input  logic c,
    input  logic d,
    output logic [3:0] mux_in
);

    // mux_in[0] for binary ab = 00
    assign mux_in[0] = c ? 1'b1 : d;

    // mux_in[1] for binary ab = 01
    assign mux_in[1] = 1'b0;

    // mux_in[2] for binary ab = 10
    assign mux_in[2] = d ? c : 1'b1;

    // mux_in[3] for binary ab = 11
    assign mux_in[3] = d ? 1'b0 : c;

endmodule

