module TopModule (
    input  logic c,
    input  logic d,
    output logic [3:0] mux_in
);

    // mux_in[0] for ab = 00: selector c, in0 = d, in1 = 1
    assign mux_in[0] = c ? 1'b1 : d;

    // mux_in[1] for ab = 01: constant 0
    assign mux_in[1] = 1'b0;

    // mux_in[2] for ab = 11: selector c, in0 = 0, in1 = d
    assign mux_in[2] = c ? d : 1'b0;

    // mux_in[3] for ab = 10: selector d, in0 = 1, in1 = c
    assign mux_in[3] = d ? c : 1'b1;

endmodule

module TopModule (
    input  logic c,
    input  logic d,
    output logic [3:0] mux_in
);

    // mux_in[0] for ab = 00 (binary): selector c, in0 = d, in1 = 1
    assign mux_in[0] = c ? 1'b1 : d;

    // mux_in[1] for ab = 01 (binary): constant 0
    assign mux_in[1] = 1'b0;

    // mux_in[2] for ab = 10 (binary, K-map col 10): selector d, in0 = 1, in1 = c
    assign mux_in[2] = d ? c : 1'b1;

    // mux_in[3] for ab = 11 (binary, K-map col 11): selector c, in0 = 0, in1 = d
    assign mux_in[3] = c ? d : 1'b0;

endmodule

module TopModule (
    input  logic c,
    input  logic d,
    output logic [3:0] mux_in
);

    // ab = 00 (binary 0): K-map col 00
    assign mux_in[0] = c ? 1'b1 : d;

    // ab = 01 (binary 1): K-map col 01
    assign mux_in[1] = 1'b0;

    // ab = 10 (binary 2): K-map col 10 (4th column, index 3)
    assign mux_in[2] = d ? c : 1'b1;

    // ab = 11 (binary 3): K-map col 11 (3rd column, index 2)
    assign mux_in[3] = c;

endmodule

module TopModule (
    input  logic c,
    input  logic d,
    output logic [3:0] mux_in
);

    // mux_in[0] corresponds to ab = 00 (K-map col 0)
    assign mux_in[0] = c ? 1'b1 : d;

    // mux_in[1] corresponds to ab = 01 (K-map col 1)
    assign mux_in[1] = 1'b0;

    // mux_in[2] corresponds to ab = 11 (K-map col 2)
    assign mux_in[2] = c ? d : 1'b0;

    // mux_in[3] corresponds to ab = 10 (K-map col 3)
    assign mux_in[3] = d ? c : 1'b1;

endmodule

module TopModule (
    input  logic c,
    input  logic d,
    output logic [3:0] mux_in
);

    // mux_in[0] for binary ab = 00
    assign mux_in[0] = c ? 1'b1 : d;

    // mux_in[1] for binary ab = 01
    assign mux_in[1] = 1'b0;

    // mux_in[2] for binary ab = 10
    assign mux_in[2] = d ? c : 1'b1;

    // mux_in[3] for binary ab = 11
    assign mux_in[3] = d ? 1'b0 : c;

endmodule
